package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.text.*;import android.text.method.LinkMovementMethod;import android.text.style.ClickableSpan;import android.view.View;import android.widget.*;import java.io.*;import java.util.*;
final class BibleLinks {
 static void bind(ReaderActivity a){if(a.bookText==null||!(a.bookText.getText() instanceof Spannable))return;final Spannable shown=(Spannable)a.bookText.getText();final String text=shown.toString();a.worker.execute(()->{List<BibleReferences.Reference> refs=BibleReferences.references(text);a.ui(()->{if(a.bookText==null||a.bookText.getText()!=shown)return;for(BibleReferences.Reference ref:refs)shown.setSpan(new ClickableSpan(){public void onClick(View v){open(a,ref);}public void updateDrawState(TextPaint ds){ds.setColor(a.accent);ds.setUnderlineText(true);}},ref.start,ref.end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);if(!refs.isEmpty()){a.bookText.setLinksClickable(true);a.bookText.setMovementMethod(LinkMovementMethod.getInstance());a.bookText.setOnTouchListener(new BibleTouch(a.bookText));}});});}
 static void query(Activity a){EditText input=PlusUi.input(a,"Livro capítulo:versículo","",160);UiDialog dialog=new UiDialog.Builder(a).setTitle("Consultar passagem bíblica").setView(input).setPositiveButton("Abrir",null).setNegativeButton("Voltar à leitura",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{List<BibleReferences.Reference> refs=BibleReferences.references(input.getText().toString());if(refs.isEmpty()){input.setError(AppLanguage.text(a,"Indique o livro, capítulo e versículo."));return;}dialog.dismiss();open(a,refs.get(0));});}
 static void open(Activity a,BibleReferences.Reference ref){PlusUi.run(a,()->{List<StudyStore.Row> sources;try(PlusStore db=new PlusStore(a)){sources=db.rows("bible_sources",null,null,"title COLLATE NOCASE",200);}PlusUi.post(a,()->{if(sources.isEmpty()){new UiDialog.Builder(a).setTitle("Passagem bíblica").setMessage("Importe uma Bíblia em Ferramentas → Bíblias para abrir as passagens dentro do Seeky.").setPositiveButton("Importar Bíblia",(d,w)->ToolsActivity.open(a,"bibles")).setNegativeButton("Fechar",null).show();return;}if(sources.size()==1)passage(a,sources.get(0),ref);else{String[] names=new String[sources.size()];for(int i=0;i<names.length;i++)names[i]=sources.get(i).s("title");new UiDialog.Builder(a).setTitle(ref.label).setItems(names,(d,n)->passage(a,sources.get(n),ref)).setNegativeButton("Fechar",null).show();}});});}
 static void passage(Activity a,StudyStore.Row source,BibleReferences.Reference ref){PlusUi.run(a,()->{List<StudyStore.Row> rows;try(PlusStore db=new PlusStore(a)){StringBuilder where=new StringBuilder("source=? AND book=? AND (");List<String> args=new ArrayList<>();args.add(""+source.id());args.add(ref.book);List<int[]> intervals=BibleReferences.intervals(ref);for(int n=0;n<intervals.size();n++){int[] range=intervals.get(n);if(n>0)where.append(" OR ");where.append("((chapter>? OR (chapter=? AND verse>=?)) AND (chapter<? OR (chapter=? AND verse<=?)))");for(int number:new int[]{range[0],range[0],range[1],range[2],range[2],range[3]})args.add(""+number);}where.append(')');rows=db.rows("bible_verses",where.toString(),args.toArray(new String[0]),"chapter,verse",501);}PlusUi.post(a,()->{if(rows.isEmpty()){PlusUi.toast(a,"Esta passagem não consta da Bíblia importada.");return;}StringBuilder value=new StringBuilder();for(StudyStore.Row row:rows.subList(0,Math.min(500,rows.size())))value.append(row.n("chapter")).append(':').append(row.n("verse")).append("  ").append(row.s("value")).append("\n\n");if(rows.size()>500)value.append(AppLanguage.text(a,"Mostrados 500 versículos. Consulte um intervalo menor."));TextView text=PlusUi.text(a,value.toString().trim(),17);text.setTextIsSelectable(true);text.setLineSpacing(PlusUi.dp(a,4),1.2f);ScrollView scroll=new ScrollView(a);scroll.addView(text);new UiDialog.Builder(a).setTitle(ref.label+" · "+source.s("title")).setView(scroll).setPositiveButton("Voltar à leitura",null).setNeutralButton("Copiar",(d,w)->((android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(ref.label,value))).show();});});}
 static void list(ReaderActivity a){a.worker.execute(()->{try{String text=a.tools!=null&&a.tools.draft!=null?a.tools.draft.text:"";if(text.isEmpty())try(SpeechDocument d=new SpeechDocument(a,a.uri,a.name,a.mime,()->a.dead)){text=d.part(a.chrome.current());}List<BibleReferences.Reference> refs=BibleReferences.references(text);a.ui(()->{if(refs.isEmpty()){PlusUi.toast(a,"Nenhuma referência bíblica reconhecida nesta parte.");return;}String[] names=new String[refs.size()];for(int i=0;i<names.length;i++)names[i]=refs.get(i).label;new UiDialog.Builder(a).setTitle("Passagens bíblicas").setItems(names,(d,n)->open(a,refs.get(n))).setNegativeButton("Fechar",null).show();});}catch(Exception e){a.ui(()->PlusUi.error(a,e));}});}
 private BibleLinks(){}
}
